import{_ as l,C as a,o as n,c as h,j as t,a as o,E as e,a5 as c}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"单选组","description":"","frontmatter":{},"headers":[],"relativePath":"components/radio-group.md","filePath":"components/radio-group.md","lastUpdated":1787598366000}'),s={name:"components/radio-group.md"},u={id:"单选组",tabindex:"-1"};function p(b,d,g,m,x,f){const i=a("Badge"),r=a("XhDemo");return n(),h("div",null,[t("h1",u,[d[0]||(d[0]=o("单选组 ",-1)),e(i,{type:"info",text:"radio-group"}),d[1]||(d[1]=o()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#单选组","aria-label":'Permalink to "单选组 <Badge type="info" text="radio-group" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一组互斥选项共一个值，所有选项同时可见。单个单选钮是这里的 <code>item</code> 部件，不另立组件——它脱离组既没有互斥对象，也无法取消选中。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>二到五个互斥选项，且各选项的文字值得同时摊开让用户比较。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>选项超过五六个：用<a href="./select">选择器</a>。</li><li>选项是并列的视图切换：用<a href="./toggle-group">切换按钮组</a>或<a href="./tabs">标签页</a>。</li><li>可以多选：用<a href="./checkbox-group">复选框组</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>整组只占一个 Tab 位，组内靠方向键走——这是原生单选组的行为。</li><li><code>hidden-input</code> 承担表单参与。</li><li><code>collection</code> 可数据驱动，也可以逐项写。</li><li>与<a href="./checkbox">复选框</a>的不对称是有意的：一个复选框自己就成立（勾选同意条款），一个单选钮自己不成立，所以复选框另有独立组件、单选钮没有。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>组内只有一个 Tab 停靠点，进组后四个方向键都能切换</p>',10)),e(r,{src:"radio-group/01-basic"}),d[4]||(d[4]=t("h3",{id:"受控",tabindex:"-1"},[o("受控 "),t("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[5]||(d[5]=t("p",null,"传了 value 就由宿主说了算；值可以是 null，表示一项都没选中",-1)),e(r,{src:"radio-group/02-controlled"}),d[6]||(d[6]=t("h3",{id:"横向排布",tabindex:"-1"},[o("横向排布 "),t("a",{class:"header-anchor",href:"#横向排布","aria-label":'Permalink to "横向排布"'},"​")],-1)),d[7]||(d[7]=t("p",null,"orientation 只影响排版与 aria-orientation，方向键四个方向照样都能切换",-1)),e(r,{src:"radio-group/03-horizontal"}),d[8]||(d[8]=t("h3",{id:"禁用",tabindex:"-1"},[o("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[9]||(d[9]=t("p",null,"单项禁用后点不动，方向键也跳过它；整组禁用则每一项都跟着禁用",-1)),e(r,{src:"radio-group/04-disabled"}),d[10]||(d[10]=t("h3",{id:"语气",tabindex:"-1"},[o("语气 "),t("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),d[11]||(d[11]=t("p",null,"tone 决定选中圆点用哪族颜色，六种语气各一组",-1)),e(r,{src:"radio-group/05-tone"}),d[12]||(d[12]=t("h3",{id:"尺寸",tabindex:"-1"},[o("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[13]||(d[13]=t("p",null,"size 改条目间距与字号，不写即缺省中档",-1)),e(r,{src:"radio-group/06-size"}),d[14]||(d[14]=t("h3",{id:"数据驱动",tabindex:"-1"},[o("数据驱动 "),t("a",{class:"header-anchor",href:"#数据驱动","aria-label":'Permalink to "数据驱动"'},"​")],-1)),d[15]||(d[15]=t("p",null,"自家字段叫什么由数据定，映射成条目的值、文本与禁用即可",-1)),e(r,{src:"radio-group/07-options"}),d[16]||(d[16]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-radio-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhRadioGroupItem</code> <code>XhRadioGroupItemText</code> <code>XhRadioGroupLabel</code> <code>XhRadioGroupRoot</code></td></tr><tr><td>组合式函数</td><td><code>useRadioGroup</code></td></tr><tr><td>状态机</td><td><code>radioGroupMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/radio-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;radio-group&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>item</code></strong> · <code>item-text</code> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>RadioGroupNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用都写在条目部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：选不动，但仍可聚焦、方向键照常移焦点，对比度不降。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改呈现，不挡交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起用，只发无障碍属性，不自行拦提交。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 &#39;ltr&#39;。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: RadioGroupValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>RadioGroupValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>FORM.RESET</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useRadioGroup</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly RadioGroupNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>(props: RadioGroupItemProps) =&gt; T[&#39;input&#39;]</code></td><td>条目对应的隐藏原生 radio 输入，用于表单提交。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点条目（即选中项）；落到容器上时由容器转投锚点条目，锚点缺席或被禁用才落首个可停留项</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in group, group not disabled</td><td>焦点移到下一个可停留条目并选中，末项回绕到首项；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in group, group not disabled</td><td>焦点移到上一个可停留条目并选中，首项回绕到末项；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Space</code></td><td>focus on item, item not disabled</td><td>选中当前条目</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/radio-group.css</code> 按部件选择：<code>[data-scope=&quot;radio-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-radio-group-gap</code> · <code>--xh-radio-group-indicator-bg</code> · <code>--xh-radio-group-indicator-border</code> · <code>--xh-radio-group-indicator-border-checked</code> · <code>--xh-radio-group-indicator-border-invalid</code> · <code>--xh-radio-group-indicator-dot</code> · <code>--xh-radio-group-indicator-radius</code> · <code>--xh-radio-group-indicator-size</code> · <code>--xh-radio-group-item-fg</code> · <code>--xh-radio-group-item-fg-disabled</code> · <code>--xh-radio-group-item-font-size</code> · <code>--xh-radio-group-item-gap</code> · <code>--xh-radio-group-item-radius</code> · <code>--xh-radio-group-label-fg</code> · <code>--xh-radio-group-label-font-size</code> · <code>--xh-radio-group-label-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>；每项下面的补充说明放进选项内容里。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>给出默认选中项，除非&quot;未选&quot;本身有意义。</li><li>选项文字写完整，别靠共同前缀省略。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>单选组只有一个选项：用户选不了别的，等于什么都没问。</li><li>选项能被取消选中：单选组一旦选中就不该回到空值，需要空值就加一项&quot;不指定&quot;。</li></ul>',40))])}const k=l(s,[["render",p]]);export{P as __pageData,k as default};
